<script setup lang="ts">
import { ArrowRight, Braces, Download, Filter, Network, Pause, Search, ShieldCheck } from '~/utils/icons'
import { alertDetailSchema, flowsResponseSchema } from '~~/shared/schemas/security'
import type { FlowRecord } from '~~/shared/types/security'
import { downloadCsv } from '~/utils/export'

const {data:flows,status,error,refresh}=await useAsyncData('flows',()=>validatedFetch('/flows',flowsResponseSchema))
const {data:sampleDetail}=await useAsyncData('sample-flow-detail',()=>validatedFetch('/alerts/ALT-78435',alertDetailSchema))
const selected=ref('');const paused=ref(false);const search=ref('');const verdict=ref('all');const protocol=ref('all');const advancedOpen=ref(false);const minimumScore=ref(0);const actionMessage=ref('')
const protocols=computed(()=>Array.from(new Set(flows.value?.items.map((row)=>row.protocol)||[])))
const filtered=computed(()=>flows.value?.items.filter((row)=>(verdict.value==='all'||row.verdict===verdict.value)&&(protocol.value==='all'||row.protocol===protocol.value)&&row.anomalyScore>=minimumScore.value&&(!search.value||`${row.id}${row.source}${row.destination}${row.service}${row.activity}`.toLowerCase().includes(search.value.toLowerCase())))||[])
const selectedFlow=computed(()=>filtered.value.find((row)=>row.id===selected.value)||filtered.value[0])
const anomalousCount=computed(()=>flows.value?.items.filter((row)=>row.verdict!=='benign').length||0)
const verdictLabels={benign:'正常',suspicious:'可疑',malicious:'恶意'}
const formatBytes=(value:number)=>value>100000?`${(value/1024).toFixed(1)} KB`:`${value.toLocaleString()} B`
function selectFlow(row:FlowRecord){selected.value=row.id}
function onRowKeydown(event:KeyboardEvent,row:FlowRecord){if(event.key==='Enter'||event.key===' '){event.preventDefault();selectFlow(row)}}
function exportFlows(){downloadCsv('evonids-flow-index-20260716.csv',['时间','Flow ID','源地址','目的地址','协议','服务','业务活动','包数','字节','持续(ms)','异常分','判定'],filtered.value.map((row)=>[row.time,row.id,`${row.source}:${row.sourcePort}`,`${row.destination}:${row.destinationPort}`,row.protocol,row.service,row.activity,row.packets,row.bytes,row.durationMs,row.anomalyScore,row.verdict]));actionMessage.value=`已导出 ${filtered.value.length} 条 Flow 索引`;setTimeout(()=>actionMessage.value='',2600)}
</script>
<template>
  <div class="traffic-page">
    <PageHeader eyebrow="Flow Detection" title="流量探索" description="逐 Flow 查看五元组、行为特征与双通道模型判定">
      <button class="page-button" :aria-pressed="paused" @click="paused=!paused"><Pause :size="13"/>{{paused?'继续流入':'暂停流入'}}</button><button class="page-button" @click="exportFlows"><Download :size="13"/>导出 PCAP 索引</button>
    </PageHeader>
    <div v-if="actionMessage" class="action-message" role="status"><ShieldCheck :size="14"/>{{actionMessage}}</div>
    <section class="flow-stats"><div><span>已载入 Flow</span><b class="mono">{{(flows?.total||0).toLocaleString()}}</b></div><div><span>异常样本</span><b class="mono warning">{{anomalousCount.toLocaleString()}}</b></div><div><span>推理基线</span><b class="mono">HGB · 42 特征</b></div><div><span>数据来源</span><b class="mono">CICIDS2017</b></div><p :class="{paused}"><i/>{{paused?'已暂停视图更新':'已载入 · 离线回放'}}</p></section>
    <section class="traffic-layout">
      <div class="flow-main">
        <section class="flow-toolbar surface-panel"><label><Search :size="14"/><input v-model="search" placeholder="Flow ID、IP、服务或业务活动…"></label><select v-model="verdict" aria-label="Flow 判定"><option value="all">全部判定</option><option value="malicious">恶意</option><option value="suspicious">可疑</option><option value="benign">正常</option></select><select v-model="protocol" aria-label="网络协议"><option value="all">全部协议</option><option v-for="item in protocols" :key="item" :value="item">{{item}}</option></select><button :class="{active:advancedOpen}" :aria-expanded="advancedOpen" @click="advancedOpen=!advancedOpen"><Filter :size="13"/>高级过滤</button><div v-if="advancedOpen" class="advanced-filter"><label><span>最低异常分</span><input v-model.number="minimumScore" type="range" min="0" max="1" step="0.05"><b class="mono">{{minimumScore.toFixed(2)}}</b></label><button @click="minimumScore=0">重置</button></div></section>
        <section class="flow-table surface-panel"><LoadingState v-if="status==='pending'" :rows="7"/><ErrorState v-else-if="error" @retry="refresh"/><EmptyState v-else-if="filtered.length===0" title="没有匹配的 Flow" description="请调整协议、判定或异常分筛选。"/><div v-else class="table-scroll"><table><thead><tr><th>时间</th><th>Flow ID</th><th>源地址</th><th>目的地址</th><th>协议 / 服务</th><th>业务活动</th><th>包 / 字节</th><th>持续</th><th>异常分</th><th>判定</th></tr></thead><tbody><tr v-for="row in filtered" :key="row.id" :class="{selected:selectedFlow?.id===row.id}" tabindex="0" :aria-selected="selectedFlow?.id===row.id" @click="selectFlow(row)" @keydown="onRowKeydown($event,row)"><td class="mono subtle">{{row.time}}</td><td class="mono">{{row.id}}</td><td class="mono">{{row.source}}:{{row.sourcePort}}</td><td class="mono">{{row.destination}}:{{row.destinationPort}}</td><td><span>{{row.protocol}}</span><small>{{row.service}}</small></td><td>{{row.activity}}</td><td><span class="mono">{{row.packets}}</span><small>{{formatBytes(row.bytes)}}</small></td><td class="mono">{{row.durationMs}} ms</td><td><span class="anomaly mono" :class="{high:row.anomalyScore>.8}">{{row.anomalyScore.toFixed(2)}}</span></td><td><span :class="['verdict',`verdict-${row.verdict}`]"><i/>{{verdictLabels[row.verdict]}}</span></td></tr></tbody></table></div><footer>显示 {{filtered.length}} 条确定性样本 Flow <span>筛选与导出基于当前结果</span></footer></section>
        <section v-if="selectedFlow?.id==='FLOW-20260716-00842'&&sampleDetail" class="mini-profile surface-panel"><div class="mini-head"><div><h2>选中 Flow 的模型判定</h2><p class="mono">{{selectedFlow.id}}</p></div><NuxtLink to="/alerts/ALT-78435">打开完整告警详情 <ArrowRight :size="12"/></NuxtLink></div><div class="channel-summary"><div><span>Flow Transformer</span><b>{{sampleDetail.transformer.prediction}}</b><em class="mono">置信度 {{Math.round(sampleDetail.transformer.confidence*100)}}%</em><small>未达到已知类别阈值</small></div><i>+</i><div><span>AutoEncoder</span><b class="warning">异常</b><em class="mono">重构误差 {{sampleDetail.autoEncoder.reconstructionError}}</em><small>超过阈值 {{sampleDetail.autoEncoder.threshold}}</small></div><i>=</i><div class="fusion"><span>最终风险</span><b class="mono">{{sampleDetail.fusion.finalScore}}</b><em>偏向未知异常</em><small>{{sampleDetail.profile.suspected_attack_type}}</small></div></div></section>
        <section v-else-if="selectedFlow" class="normal-explain surface-panel"><ShieldCheck :size="18"/><div><h2>{{selectedFlow.verdict==='benign'?'正常流量，不生成高危告警':'该 Flow 进入异常聚合队列'}}</h2><p>当前异常分 <code>{{selectedFlow.anomalyScore.toFixed(2)}}</code>；{{selectedFlow.verdict==='benign'?'Flow Transformer 判定为 Benign，AutoEncoder 重构误差位于正常阈值内。':'需要结合时间窗口行为生成结构化画像。'}}</p></div></section>
      </div>
      <aside class="flow-side">
        <section class="graph-panel surface-panel"><div class="side-head"><div><h2>当前 Flow 通信关系</h2><p>源地址 → 目标资产 / 端口</p></div><Network :size="15"/></div><AttackGraph v-if="selectedFlow" :source="selectedFlow.source" :destination="`${selectedFlow.destination}:${selectedFlow.destinationPort}`" :ports="selectedFlow.id==='FLOW-20260716-00842'?76:1" :targets="selectedFlow.id==='FLOW-20260716-00842'?18:1" :metric-label="selectedFlow.id==='FLOW-20260716-00842'?'SYN 比例':'异常分'" :metric-value="selectedFlow.id==='FLOW-20260716-00842'?'0.82':selectedFlow.anomalyScore.toFixed(2)" :multi-target="selectedFlow.id==='FLOW-20260716-00842'"/></section>
        <section class="raw-panel surface-panel"><div class="side-head"><div><h2>数据溯源</h2><p>当前回放批次与特征版本</p></div><Braces :size="15"/></div><dl><div><dt>Dataset</dt><dd class="mono">CICIDS2017</dd></div><div><dt>Ingest</dt><dd class="mono">PCAP 离线回放</dd></div><div><dt>Model</dt><dd class="mono">HGB baseline</dd></div><div><dt>Features</dt><dd class="mono">42 numeric</dd></div><div><dt>Live sensor</dt><dd class="mono">未接入</dd></div></dl></section>
      </aside>
    </section>
  </div>
</template>
<style scoped>
.traffic-page{padding:20px 22px 28px}.page-button{display:flex;align-items:center;gap:5px;height:34px;padding:0 9px;border:1px solid var(--border-default);border-radius:8px;background:var(--surface-1);color:var(--text-secondary);font-size:13px;cursor:pointer}.action-message{display:flex;align-items:center;gap:6px;margin-bottom:10px;padding:8px 10px;border:1px solid color-mix(in srgb,var(--status-success) 34%,var(--border-default));border-radius:7px;color:var(--status-success);font-size:13px}.flow-stats{display:grid;grid-template-columns:repeat(4,auto) 1fr;align-items:center;min-height:53px;margin-bottom:12px;border-block:1px solid var(--border-default);background:var(--surface-1)}.flow-stats>div{padding:7px 14px;border-right:1px solid var(--border-subtle)}.flow-stats span,.flow-stats b{display:block}.flow-stats span{color:var(--text-tertiary);font-size:12px}.flow-stats b{font-size:14px}.good{color:var(--status-success)!important}.flow-stats p{display:flex;justify-self:end;align-items:center;gap:5px;margin:0;padding:0 14px;color:var(--status-success);font-size:12px}.flow-stats p i{width:6px;height:6px;border-radius:50%;background:var(--status-success)}.flow-stats p.paused{color:var(--status-warning)}.flow-stats p.paused i{background:var(--status-warning)}.traffic-layout{display:grid;grid-template-columns:minmax(0,1fr) 295px;gap:12px}.flow-main{min-width:0}.flow-toolbar{display:grid;grid-template-columns:minmax(220px,1fr) 125px 110px auto;gap:7px;margin-bottom:10px;padding:8px}.flow-toolbar>label{position:relative}.flow-toolbar>label svg{position:absolute;top:8px;left:9px;color:var(--text-tertiary)}.flow-toolbar input,.flow-toolbar select,.flow-toolbar button{width:100%;height:30px;border:1px solid var(--border-default);border-radius:6px;background:var(--surface-2);color:var(--text-secondary);font-size:12px}.flow-toolbar>label>input{padding:0 8px 0 29px}.flow-toolbar select{padding:0 6px}.flow-toolbar button{display:flex;align-items:center;justify-content:center;gap:4px;cursor:pointer}.flow-toolbar>button.active{border-color:var(--accent);color:var(--accent-strong);background:var(--accent-muted)}.advanced-filter{grid-column:1/-1;display:grid;grid-template-columns:1fr auto;gap:8px;align-items:center;padding:8px;border-top:1px solid var(--border-subtle)}.advanced-filter label{display:grid;grid-template-columns:auto 1fr 40px;gap:8px;align-items:center;color:var(--text-tertiary);font-size:12px}.advanced-filter input{height:auto;padding:0}.advanced-filter b{text-align:right}.advanced-filter button{width:auto;padding:0 10px}.flow-table{overflow:hidden;margin-bottom:10px}.table-scroll{overflow-x:auto}.flow-table table{width:100%;min-width:900px;border-collapse:collapse}.flow-table th{height:29px;padding:0 8px;background:var(--surface-2);color:var(--text-tertiary);font-size:12px;text-align:left}.flow-table td{height:40px;padding:4px 8px;border-top:1px solid var(--border-subtle);color:var(--text-secondary);font-size:12px;white-space:nowrap}.flow-table tbody tr{cursor:pointer}.flow-table tbody tr:hover,.flow-table tbody tr.selected{background:var(--surface-2)}.flow-table tbody tr.selected{box-shadow:inset 2px 0 var(--accent)}.subtle{color:var(--text-tertiary)!important}.flow-table td small{display:block;color:var(--text-tertiary);font-size:12px}.anomaly{display:inline-grid;width:28px;height:21px;place-items:center;border-radius:4px;background:var(--surface-3)}.anomaly.high{background:color-mix(in srgb,var(--severity-high) 10%,transparent);color:var(--severity-high)}.verdict{display:flex;align-items:center;gap:4px}.verdict i{width:5px;height:5px;border-radius:50%;background:var(--text-tertiary)}.verdict-benign i{background:var(--status-success)}.verdict-suspicious i{background:var(--status-warning)}.verdict-malicious i{background:var(--status-error)}.flow-table footer{display:flex;justify-content:space-between;align-items:center;min-height:34px;padding:0 9px;border-top:1px solid var(--border-subtle);background:var(--surface-2);color:var(--text-tertiary);font-size:12px}.mini-profile{overflow:hidden}.mini-head{display:flex;justify-content:space-between;align-items:center;min-height:43px;padding:7px 11px;border-bottom:1px solid var(--border-subtle)}.mini-head h2,.mini-head p{margin:0}.mini-head h2{font-size:13px}.mini-head p{margin-top:2px;color:var(--text-tertiary);font-size:12px}.mini-head a{display:flex;align-items:center;gap:4px;color:var(--accent-strong);font-size:12px;text-decoration:none}.channel-summary{display:grid;grid-template-columns:1fr 20px 1fr 20px .8fr;align-items:center}.channel-summary>div{padding:9px 11px}.channel-summary>i{color:var(--text-tertiary);font-size:12px;font-style:normal;text-align:center}.channel-summary span,.channel-summary b,.channel-summary em,.channel-summary small{display:block}.channel-summary span{color:var(--text-tertiary);font-size:12px}.channel-summary b{margin-top:2px;font-size:12px}.channel-summary b.warning{color:var(--status-warning)}.channel-summary em{margin-top:2px;color:var(--text-secondary);font-size:12px;font-style:normal}.channel-summary small{color:var(--text-tertiary);font-size:12px}.channel-summary .fusion{background:var(--surface-2)}.channel-summary .fusion b{color:var(--severity-high);font-size:19px}.normal-explain{display:flex;align-items:center;gap:10px;padding:12px;color:var(--status-success)}.normal-explain h2,.normal-explain p{margin:0}.normal-explain h2{color:var(--text-primary);font-size:13px}.normal-explain p{margin-top:2px;color:var(--text-tertiary);font-size:12px}.flow-side{display:grid;align-content:start;gap:10px}.graph-panel,.raw-panel{overflow:hidden}.side-head{display:flex;justify-content:space-between;align-items:center;min-height:44px;padding:7px 10px;border-bottom:1px solid var(--border-subtle)}.side-head h2,.side-head p{margin:0}.side-head h2{font-size:13px}.side-head p{margin-top:2px;color:var(--text-tertiary);font-size:12px}.side-head>svg{color:var(--accent-strong)}.graph-facts{display:grid;grid-template-columns:repeat(3,1fr);border-top:1px solid var(--border-subtle)}.graph-facts span{padding:7px;border-right:1px solid var(--border-subtle);color:var(--text-tertiary);font-size:12px}.graph-facts span:last-child{border-right:0}.graph-facts b{display:block;color:var(--text-secondary);font-size:13px}.raw-panel dl{margin:0}.raw-panel dl div{display:flex;justify-content:space-between;min-height:31px;padding:0 10px;align-items:center;border-bottom:1px solid var(--border-subtle)}.raw-panel dt,.raw-panel dd{font-size:12px}.raw-panel dt{color:var(--text-tertiary)}.raw-panel dd{margin:0;color:var(--text-secondary)}
@media(max-width:1050px){.traffic-layout{grid-template-columns:1fr}.flow-side{grid-template-columns:1fr 1fr}}@media(max-width:650px){.traffic-page{padding:16px 12px 24px}.flow-stats{grid-template-columns:1fr 1fr}.flow-stats>div:nth-child(n+3),.flow-stats p{display:none}.flow-toolbar{grid-template-columns:1fr 1fr}.flow-toolbar>label{grid-column:1/-1}.advanced-filter{display:none}.channel-summary{grid-template-columns:1fr}.channel-summary>i{display:none}.flow-side{grid-template-columns:1fr}}
.flow-table table{min-width:1080px}.flow-table td:nth-child(6){max-width:190px;white-space:normal}
@media(max-width:650px){.flow-stats>div:nth-child(n+3){display:block}.flow-stats p{display:flex;grid-column:1/-1;justify-self:stretch;min-height:36px}.advanced-filter{display:grid}}
</style>
